#!/usr/bin/env bash
set -Eeuo pipefail

VERSION="2.5.0"
APP_VERSION="NOVA-2.5.0"
REV="CLEAN-REALTIME-CORE-R4-ENTRYPOINT-FIX-VERIFIED-2X"
ZIP_NAME="QUANT_NOVA_2.5.0_CLEAN_REALTIME_CORE_R3_LOWMEM.zip"
ROOT_NAME="nova2500"
EXPECTED_ZIP_SHA256="026baf336156916a03651f98887580c729e9e6ca8fa0c4a4b762d4cb5ab57f66"
APP_DIR="$HOME/quant-nova"
CONTAINER="quant-nova"
NETWORK="kiwoom-net"
HOST_PORT="3200"
IMAGE="quant-nova:2.5.0-clean-r4-entrypoint-${EXPECTED_ZIP_SHA256:0:12}"
STAMP="$(date +%Y%m%d%H%M%S)"
BACKUP="quant-nova-backup-clean250-r4-${STAMP}"
FAILED="quant-nova-failed-clean250-r4-${STAMP}"
STAGE="quant-nova-stage-clean250-r4-${STAMP}"
CANDIDATE="quant-nova-candidate-clean250-r4-${STAMP}"
TMP="$(mktemp -d)"
DEPLOY_DIR="$APP_DIR/deployments/clean250-r4-$STAMP"
GUARD_STATIC="$APP_DIR/http-guard-v2/static"
GUARD_CACHE="$APP_DIR/http-guard-v2/cache"
GUARD_BK="$DEPLOY_DIR/http-guard-static-before"
RUNTIME_ENV="$TMP/runtime.env"
CUTOVER=0
SUCCESS=0
GUARD_SYNCED=0
OLD_RENAMED=0

say(){ printf '\n==> %s\n' "$*"; }

on_exit(){
  ec=$?
  trap - EXIT
  sudo docker rm -f "$CANDIDATE" >/dev/null 2>&1 || true
  sudo docker rm -f "$STAGE" >/dev/null 2>&1 || true
  if [[ $SUCCESS -ne 1 && $CUTOVER -eq 1 ]]; then
    echo "[자동복구] R4 cutover 실패 — 직전 컨테이너 복구" >&2
    if sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
      sudo docker stop -t 5 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
      sudo docker rename "$CONTAINER" "$FAILED" >/dev/null 2>&1 || true
    fi
    if [[ $OLD_RENAMED -eq 1 ]] && sudo docker inspect "$BACKUP" >/dev/null 2>&1; then
      sudo docker rename "$BACKUP" "$CONTAINER" >/dev/null 2>&1 || true
      sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
    fi
    if [[ $GUARD_SYNCED -eq 1 && -d "$GUARD_BK" && -d "$GUARD_STATIC" ]]; then
      sudo rm -rf "$GUARD_STATIC"/* >/dev/null 2>&1 || true
      sudo cp -a "$GUARD_BK"/. "$GUARD_STATIC"/ >/dev/null 2>&1 || true
      sudo rm -f "$GUARD_CACHE"/* >/dev/null 2>&1 || true
    fi
  fi
  rm -rf "$TMP" >/dev/null 2>&1 || true
  if [[ $SUCCESS -eq 1 ]]; then exit 0; else exit "${ec:-1}"; fi
}
trap on_exit EXIT

[[ "$(id -u)" -ne 0 ]] || { echo "ubuntu 사용자로 실행하세요." >&2; exit 1; }
mkdir -p "$DEPLOY_DIR"

say "0/8 R3 원칙 — NO SERVER LOADTEST / NO DOCKER BUILD / SHADOW BEFORE CUTOVER"
EMERGENCY="${NOVA_EMERGENCY_DEPLOY:-NO}"
if [[ "$EMERGENCY" != "YES" ]]; then
  echo "이 파일은 장애복구용입니다. NOVA_EMERGENCY_DEPLOY=YES 로 실행하세요." >&2
  exit 2
fi

echo "POLICY=LOW_MEMORY_RUNTIME_TRANSPLANT"
echo "ACTIVE_CONTAINER_UNTOUCHED_UNTIL_SHADOW_PASS=YES"
echo "SERVER_LOADTEST=DISABLED"
echo "DOCKER_BUILD=DISABLED"

say "1/8 사전점검 — 현재 컨테이너/Key/Data/자원 보존"
for c in python3 curl sha256sum base64 awk df; do command -v "$c" >/dev/null 2>&1 || { echo "필수 명령 없음: $c" >&2; exit 1; }; done
sudo docker info >/dev/null 2>&1 || { echo "Docker daemon 접근 실패" >&2; exit 1; }
[[ -s "$APP_DIR/.env" ]] || { echo "$APP_DIR/.env 없음" >&2; exit 1; }
[[ -d "$APP_DIR/data" ]] || { echo "$APP_DIR/data 없음" >&2; exit 1; }
sudo docker inspect "$CONTAINER" >/dev/null 2>&1 || { echo "현재 quant-nova 컨테이너 없음 — rollback 원본이 없어 중단" >&2; exit 1; }
FREE_KB="$(df -Pk "$HOME" | awk 'NR==2{print $4}')"; [[ ${FREE_KB:-0} -ge 524288 ]] || { echo "디스크 여유 512MB 미만" >&2; exit 1; }
MEMORY_BEFORE="$(free -m | awk '/Mem:/{printf "used=%sMB available=%sMB",$3,$7}')"
echo "MEMORY_BEFORE=$MEMORY_BEFORE"
SWAP_BEFORE="$(free -m | awk '/Swap:/{printf "used=%sMB free=%sMB",$3,$4}')"
echo "SWAP_BEFORE=$SWAP_BEFORE"
BASE_IMAGE_ID="$(sudo docker inspect "$CONTAINER" --format '{{.Image}}')"
[[ -n "$BASE_IMAGE_ID" ]] || { echo "기존 image id 확인 실패" >&2; exit 1; }
sudo docker inspect "$BASE_IMAGE_ID" >/dev/null 2>&1 || { echo "기존 image가 로컬에 없음" >&2; exit 1; }
sudo docker inspect "$CONTAINER" --format '{{range .Config.Env}}{{println .}}{{end}}' > "$RUNTIME_ENV"
chmod 600 "$RUNTIME_ENV"
if curl -fsS --connect-timeout 1 --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/health" >/dev/null 2>&1; then
  echo "ACTIVE_BASELINE_HEALTH=PASS"
else
  echo "ACTIVE_BASELINE_HEALTH=FAIL (emergency replacement continues; active remains untouched until shadow pass)"
fi

say "2/8 CLEAN R3 패키지 복원 + SHA + exact manifest"
base64 -d > "$TMP/$ZIP_NAME" <<'NOVA250_R3_PAYLOAD'
