NOVA250_R3_PAYLOAD
ACTUAL="$(sha256sum "$TMP/$ZIP_NAME" | awk '{print $1}')"
[[ "$ACTUAL" == "$EXPECTED_ZIP_SHA256" ]] || { echo "ZIP SHA 불일치 expected=$EXPECTED_ZIP_SHA256 actual=$ACTUAL" >&2; exit 1; }
python3 - "$TMP/$ZIP_NAME" "$TMP" <<'PYEX'
import sys,zipfile
z=zipfile.ZipFile(sys.argv[1]);bad=z.testzip();assert bad is None,bad;z.extractall(sys.argv[2])
print('ZIP_TEST=PASS')
PYEX
ROOT="$TMP/$ROOT_NAME"
python3 "$ROOT/scripts/build_context_check.py" --mode package
(cd "$ROOT" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null)
python3 - "$ROOT/BUILD_INFO.json" <<'PYBI'
import json,sys
b=json.load(open(sys.argv[1]))
assert b.get('version')=='NOVA-2.5.0',b
assert b.get('policy')=='CLEAN_REALTIME_CORE_R3_LOW_MEMORY',b
assert b.get('installer_rev')=='2.5.0-CLEAN-REALTIME-CORE-R3-LOWMEM',b
assert b.get('aws_loadtest')=='OFFLINE_ONLY',b
print('BUILD_INFO=PASS')
PYBI

say "3/8 Host 경량 정적 Gate — 부하시험/빌드 없음"
python3 -m py_compile "$ROOT/app/main.py" "$ROOT/app/realtime_core.py" "$ROOT/app/runtime_health.py" "$ROOT/app/evidence_engine.py" "$ROOT/app/archive_engine.py" "$ROOT/app/shadow_engine.py" "$ROOT/app/rs_shadow_engine.py" "$ROOT/scripts/replay_backtest.py" "$ROOT/scripts/selfcheck.py" "$ROOT/scripts/build_context_check.py"
if command -v node >/dev/null 2>&1; then node --check "$ROOT/static/nova.js"; else echo "NODE_CHECK=SKIP"; fi
grep -Fq "APP_VERSION='NOVA-2.5.0'" "$ROOT/app/main.py"
grep -Fq "@app.get('/api/livez')" "$ROOT/app/main.py"
grep -Fq "@app.get('/api/realtime-health')" "$ROOT/app/main.py"
grep -Fq "@app.get('/api/opening-profit-bridge')" "$ROOT/app/main.py"
grep -Fq "@app.get('/api/signal-history/{code}')" "$ROOT/app/main.py"
echo "HOST_STATIC_GATE=PASS"

say "4/8 Low-memory immutable image 생성 — 기존 image 기반 staging + CLEAN source 주입"
sudo docker rm -f "$STAGE" >/dev/null 2>&1 || true
sudo docker create --name "$STAGE" --network none --user 0:0 --entrypoint /bin/sh "$BASE_IMAGE_ID" -c 'sleep 3600' >/dev/null
sudo docker start "$STAGE" >/dev/null
sudo docker exec "$STAGE" /bin/sh -lc 'find /app -mindepth 1 -maxdepth 1 ! -name data -exec rm -rf -- {} +; mkdir -p /app'
for x in app static config scripts; do sudo docker cp "$ROOT/$x" "$STAGE:/app/$x"; done
for x in BUILD_INFO.json SOURCE_MANIFEST.sha256 ARCHITECTURE_CLEAN_2.5.0.md DEPLOYMENT_GATES.md README_KO.md REBUILD_AUDIT_20260812.txt requirements.txt; do sudo docker cp "$ROOT/$x" "$STAGE:/app/$x"; done
sudo docker exec "$STAGE" python /app/scripts/build_context_check.py --mode runtime
sudo docker exec "$STAGE" python -c 'import fastapi,uvicorn,httpx,websockets,pywebpush,cryptography;print("RUNTIME_DEPS=PASS")'
sudo docker exec "$STAGE" python -m py_compile /app/app/main.py /app/app/realtime_core.py /app/app/runtime_health.py /app/app/evidence_engine.py /app/app/archive_engine.py /app/app/shadow_engine.py /app/app/rs_shadow_engine.py /app/scripts/selfcheck.py /app/scripts/build_context_check.py
sudo docker exec -e NOVA_DATA_DIR=/tmp/nova-selfcheck "$STAGE" python /app/scripts/selfcheck.py >/dev/null
echo "STAGING_SELFCHECK=PASS"
sudo docker exec "$STAGE" /bin/sh -lc 'find /app -type d -name __pycache__ -prune -exec rm -rf {} +; find /app -type f -name "*.pyc" -delete' >/dev/null 2>&1 || true
sudo docker commit \
  --change 'ENV PYTHONDONTWRITEBYTECODE=1 PYTHONUNBUFFERED=1 PORT=8000 NOVA_DATA_DIR=/app/data' \
  --change 'WORKDIR /app' \
  --change 'ENTRYPOINT []' \
  --change 'CMD ["python","-m","uvicorn","app.main:app","--host","0.0.0.0","--port","8000"]' \
  "$STAGE" "$IMAGE" >/dev/null
sudo docker rm -f "$STAGE" >/dev/null
sudo docker image inspect "$IMAGE" >/dev/null

say "5/8 Shadow Candidate — 별도 port/data, active는 계속 그대로"
sudo docker network inspect "$NETWORK" >/dev/null 2>&1 || sudo docker network create "$NETWORK" >/dev/null
CAND_PORT="$(python3 - <<'PYPORT'
import socket
s=socket.socket();s.bind(('127.0.0.1',0));print(s.getsockname()[1]);s.close()
PYPORT
)"
mkdir -p "$TMP/candidate-data"; chmod 700 "$TMP/candidate-data"
sudo docker run -d --name "$CANDIDATE" --network "$NETWORK" --env-file "$RUNTIME_ENV" \
  -e PORT=8000 -e NOVA_DATA_DIR=/app/data -e NOVA_CANDIDATE_MODE=1 \
  -v "$TMP/candidate-data:/app/data" -p "127.0.0.1:${CAND_PORT}:8000" \
  --entrypoint /bin/sh "$IMAGE" -c 'exec python -m uvicorn app.main:app --host 0.0.0.0 --port "${PORT:-8000}"' >/dev/null
CAND_OK=0
for i in $(seq 1 60); do
  J="$(curl -fsS --connect-timeout 1 --max-time 2 "http://127.0.0.1:${CAND_PORT}/api/livez" 2>/dev/null || true)"
  if [[ -n "$J" ]] && printf '%s' "$J" | python3 -c 'import sys,json;j=json.load(sys.stdin);raise SystemExit(0 if j.get("ok") and j.get("version")=="NOVA-2.5.0" and j.get("candidate_mode") is True else 1)' 2>/dev/null; then CAND_OK=1;break;fi
  sleep .25
done
[[ $CAND_OK -eq 1 ]] || { sudo docker logs --tail 200 "$CANDIDATE" || true; echo "candidate livez 실패" >&2; exit 1; }
RH="$(curl -fsS --connect-timeout 1 --max-time 3 "http://127.0.0.1:${CAND_PORT}/api/realtime-health")"
printf '%s' "$RH" | python3 -c 'import sys,json;j=json.load(sys.stdin);assert j.get("ok") is True,j; assert int((j.get("lane") or {}).get("critical_overflow_events") or 0)==0,j; assert int((j.get("lane") or {}).get("handler_errors") or 0)==0,j; print("CANDIDATE_RT_HEALTH=PASS")'
for i in $(seq 1 12); do
  curl -fsS -o /dev/null --connect-timeout 1 --max-time 1.5 "http://127.0.0.1:${CAND_PORT}/api/livez" || { echo "candidate soak fail $i" >&2; exit 1; }
  sleep .10
done
echo "CANDIDATE_SOAK=PASS"
sudo docker rm -f "$CANDIDATE" >/dev/null

say "6/8 Atomic cutover — Shadow 통과 후 처음으로 active 교체"
if [[ -d "$GUARD_STATIC" ]]; then
  mkdir -p "$GUARD_BK"
  sudo cp -a "$GUARD_STATIC"/. "$GUARD_BK"/ >/dev/null 2>&1 || true
fi
CUTOVER=1
sudo docker stop -t 15 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
sudo docker rename "$CONTAINER" "$BACKUP"; OLD_RENAMED=1
sudo docker run -d --name "$CONTAINER" --restart unless-stopped \
  --log-opt max-size=10m --log-opt max-file=3 \
  --network "$NETWORK" --env-file "$RUNTIME_ENV" \
  -e PORT=8000 -e NOVA_DATA_DIR=/app/data -e NOVA_CANDIDATE_MODE=0 \
  -v "$APP_DIR/data:/app/data" -p "${HOST_PORT}:8000" \
  --entrypoint /bin/sh "$IMAGE" -c 'exec python -m uvicorn app.main:app --host 0.0.0.0 --port "${PORT:-8000}"' >/dev/null

say "7/8 Final live Gate + Public UI atomic sync"
LIVE_OK=0
for i in $(seq 1 80); do
  J="$(curl -fsS --connect-timeout 1 --max-time 2 "http://127.0.0.1:${HOST_PORT}/api/livez" 2>/dev/null || true)"
  if [[ -n "$J" ]] && printf '%s' "$J" | python3 -c 'import sys,json;j=json.load(sys.stdin);raise SystemExit(0 if j.get("ok") and j.get("version")=="NOVA-2.5.0" and j.get("candidate_mode") is False else 1)' 2>/dev/null; then LIVE_OK=1;break;fi
  sleep .25
done
[[ $LIVE_OK -eq 1 ]] || { sudo docker logs --tail 250 "$CONTAINER" || true; echo "final livez 실패" >&2; exit 1; }
for i in $(seq 1 12); do curl -fsS -o /dev/null --connect-timeout 1 --max-time 2 "http://127.0.0.1:${HOST_PORT}/api/livez" || { echo "final liveness fail $i" >&2; exit 1; }; sleep .1; done
RH="$(curl -fsS --connect-timeout 1 --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/realtime-health")"
printf '%s' "$RH" | python3 -c 'import sys,json;j=json.load(sys.stdin);assert j.get("ok") is True,j;assert int((j.get("lane") or {}).get("critical_overflow_events") or 0)==0,j;assert int((j.get("lane") or {}).get("handler_errors") or 0)==0,j;print("FINAL_RT_HEALTH=PASS")'
if curl -fsS --connect-timeout 1 --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/ws-contract" > "$TMP/ws.json" 2>/dev/null; then
  python3 - "$TMP/ws.json" <<'PYWS'
import json,sys
j=json.load(open(sys.argv[1]));c=j.get('contract') or {}
assert (c.get('trade_type'),c.get('program_type'),c.get('orderbook_type'))==('0B','0u','0D'),c
print('WS_CONTRACT=PASS 0B/0u/0D')
PYWS
else
  echo "WS_CONTRACT_ENDPOINT=SKIP(no response)"
fi
if [[ -d "$GUARD_STATIC" ]]; then
  for f in index.html nova.js nova.css sw.js manifest.webmanifest icon-192.png icon-512.png; do
    [[ -f "$ROOT/static/$f" ]] || continue
    sudo cp "$ROOT/static/$f" "$GUARD_STATIC/.$f.r3.tmp"
    sudo chmod 644 "$GUARD_STATIC/.$f.r3.tmp"
    sudo mv "$GUARD_STATIC/.$f.r3.tmp" "$GUARD_STATIC/$f"
  done
  sudo rm -f "$GUARD_CACHE"/* >/dev/null 2>&1 || true
  GUARD_SYNCED=1
fi

say "8/8 Deployment seal"
cat > "$DEPLOY_DIR/DEPLOYMENT_OK.txt" <<EOF
status=PASS
version=NOVA-2.5.0
rev=$REV
zip_sha256=$EXPECTED_ZIP_SHA256
image=$IMAGE
base_image=$BASE_IMAGE_ID
server_loadtest=DISABLED_OFFLINE_ONLY
package_gate=PASS
runtime_gate=PASS
staging_selfcheck=PASS
candidate_soak=PASS
final_livez=PASS
final_realtime_health=PASS
rollback_backup=$BACKUP
completed_at=$(date -Is)
EOF
SUCCESS=1
echo "=== NOVA 2.5.0 CLEAN R4 ENTRYPOINT VERIFIED DEPLOY PASS ==="
echo "BACKUP_PRESERVED=$BACKUP"
MEMORY_AFTER="$(free -m | awk '/Mem:/{printf "used=%sMB available=%sMB",$3,$7}')"
echo "MEMORY_AFTER=$MEMORY_AFTER"
SWAP_AFTER="$(free -m | awk '/Swap:/{printf "used=%sMB free=%sMB",$3,$4}')"
echo "SWAP_AFTER=$SWAP_AFTER"
